/* styles.css, linked with <link rel="stylesheet" href="styles.css"> */
body {
  font-family: system-ui, sans-serif;
  margin: 0;
}

h1, h2 {                 /* one rule, two selectors */
  color: #1e3a8a;
  line-height: 1.2;
}

.notice {
  colr: red;             /* typo: dropped, developer tools show a warning */
  background: #fef3c7;               /* fallback for older browsers */
  background: oklch(96% 0.05 90);    /* newer colour format, used if understood */
}

:root { font-size: 100%; }  /* :root = the <html> element; keeps the reader's setting */

.card {
  color: #1f2937;
  background: oklch(97% 0.02 250);   /* very light blue */
  border: 1px solid rgb(0 0 0 / 10%);
  padding: 1.5rem;                   /* 24px at the default size */
  max-width: 60ch;                   /* comfortable line length */
  width: calc(100% - 2rem);
}

.card button { font-size: 0.875rem; padding: 0.5em 1em; } /* em: grows with its text */
.hero { min-height: 100dvh; }        /* full visible height on phones */
.icon { fill: currentColor; }        /* follows the text colour */

/* the usual first line: * = every element (::before and ::after come later) */
*, *::before, *::after { box-sizing: border-box; }

.card {
  width: 300px;              /* total width: exactly 300px with border-box */
  padding: 20px;
  border: 1px solid #ccc;
  margin-block: 16px;        /* top and bottom */
  margin-inline: auto;       /* centres the card horizontally */
}

p { margin-block: 1em; }     /* paragraphs end up 1em apart, not 2em (collapse) */

.button { padding: 0.5rem 1rem; }  /* 0.5rem top/bottom, 1rem left/right */

/* <p>Text <span class="badge">new</span> more text</p> */
.badge {
  display: inline-block;     /* sits in the line, but accepts padding and size */
  padding: 2px 8px;
  border-radius: 999px;
  background: #e0f2fe;
}

nav a { display: block; }    /* each link on its own full-width line */

.toolbar { display: inline-flex; gap: 4px; }  /* inline box, flex children */

.is-hidden { display: none; }

.visually-hidden {           /* hidden on screen, still read aloud */
  position: absolute; width: 1px; height: 1px; overflow: hidden;
  clip-path: inset(50%); white-space: nowrap;
}

@font-face {
  font-family: "Inter";
  src: url("/fonts/InterVariable.woff2") format("woff2");
  font-weight: 100 900;          /* variable font: one file, all weights */
  font-display: swap;
}

body {
  font-family: "Inter", system-ui, sans-serif;
  font-size: 1rem;
  line-height: 1.5;              /* no unit: scales with each element's text */
  color: #222;
}

article { max-width: 65ch; }

h1 {
  font-size: clamp(1.75rem, 1.2rem + 2.5vw, 3rem);  /* grows with the screen */
  font-weight: 750;
  line-height: 1.1;
  letter-spacing: -0.01em;
}

.card {
  background: white;
  border: 1px solid oklch(90% 0 0);
  border-radius: 12px;
  box-shadow: 0 1px 2px rgb(0 0 0 / 6%), 0 8px 24px rgb(0 0 0 / 8%);
}

.hero {
  background:
    linear-gradient(rgb(0 0 0 / 40%), rgb(0 0 0 / 40%)),  /* dark layer on top */
    url("/img/hero.jpg") center / cover no-repeat;
  color: white;
}

.avatar { width: 48px; height: 48px; border-radius: 50%; }

/* :focus-visible (a later lesson) = when the keyboard is on this button */
button:focus-visible { outline: 3px solid #2563eb; outline-offset: 2px; }

/* <header class="bar"><a>Logo</a><nav>...</nav><button>Sign in</button></header> */
.bar {
  display: flex;
  align-items: center;           /* vertical centring in a row */
  gap: 1rem;
  padding: 0.5rem 1rem;
}
.bar button { margin-left: auto; }   /* pushes the button to the far right */

.center {                        /* centre anything both ways */
  display: flex; justify-content: center; align-items: center;
  min-height: 50vh;
}

.cards { display: flex; flex-wrap: wrap; gap: 1rem; }
.cards > * { flex: 1 1 250px; }  /* at least ~250px, grow to fill each line */

.sidebar-layout { display: flex; }
.sidebar-layout aside { flex: 0 0 240px; }   /* fixed */
.sidebar-layout main  { flex: 1; }           /* takes the rest */

a:hover { text-decoration-thickness: 2px; }
button:focus-visible { outline: 3px solid royalblue; }   /* keyboard focus only */

tr:nth-child(even) { background: #f5f5f5; }  /* zebra rows */
li:not(:last-child) { border-bottom: 1px solid #eee; }

input:user-invalid { border-color: crimson; } /* only after the user interacts */

.required::after { content: " *"; color: crimson; }

blockquote::before {          /* decorative quote mark */
  content: "\201C";
  font-size: 3rem;
  line-height: 0;
}

li::marker { color: teal; }
::selection { background: #fde68a; }

/* <div class="card"><span class="badge">New</span>...</div> */
.card { position: relative; }      /* containing block for the badge */
.badge {
  position: absolute;
  top: 8px;
  right: 8px;
}

.overlay { position: absolute; inset: 0; background: rgb(0 0 0 / 50%); }

.site-header {
  position: sticky;
  top: 0;                          /* sticks when it reaches the top */
  background: white;
  z-index: 10;
}

.chat-button { position: fixed; right: 1rem; bottom: 1rem; }

/* <div class="page"><header/><aside/><main/><footer/></div> */
.page {
  display: grid;
  grid-template-columns: 240px 1fr;
  grid-template-rows: auto 1fr auto;
  grid-template-areas:
    "head head"
    "side main"
    "foot foot";
  min-height: 100dvh;
  gap: 1rem;
}
.page > header { grid-area: head; }
.page > aside  { grid-area: side; }
.page > main   { grid-area: main; }
.page > footer { grid-area: foot; }

.gallery {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));  /* responsive */
  gap: 12px;
}
.gallery .featured { grid-column: span 2; }

img { max-width: 100%; height: auto; }      /* never overflow the container */

.container { width: min(100% - 2rem, 70rem); margin-inline: auto; }

.thumb {
  width: 100%;
  aspect-ratio: 4 / 3;
  object-fit: cover;                         /* crop, don't stretch */
  object-position: center top;
}

.title { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

.excerpt {                                   /* three lines, then ... */
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
  overflow: hidden;
}

.comment { overflow-wrap: anywhere; }        /* break very long URLs */
.panel { max-height: 20rem; overflow-y: auto; }

/* mobile first: single column by default */
.layout { display: grid; gap: 1rem; }
.nav-links { display: none; }

@media (width >= 48rem) {             /* tablets and up */
  .layout { grid-template-columns: 220px 1fr; }
  .nav-links { display: flex; gap: 1rem; }
  .menu-button { display: none; }
}

@media (width >= 80rem) {             /* wide screens */
  .layout { grid-template-columns: 260px 1fr 300px; }
}

@media (prefers-reduced-motion: reduce) {
  * { animation-duration: 0.01ms !important; transition-duration: 0.01ms !important; }
}

@media (hover: hover) { .card:hover { transform: translateY(-2px); } }
@media print { nav, .ads { display: none; } }

.button {
  background: #4f46e5;
  transition: background-color 150ms ease, translate 150ms ease;
}
.button:hover { background: #4338ca; translate: 0 -1px; }

@keyframes fade-up {
  from { opacity: 0; translate: 0 12px; }
  to   { opacity: 1; translate: 0 0; }
}
.toast { animation: fade-up 300ms ease-out both; }

@keyframes spin { to { rotate: 1turn; } }
.spinner { animation: spin 0.8s linear infinite; }

/* popover that fades in when shown */
[popover] { opacity: 0; transition: opacity 200ms, display 200ms allow-discrete; }
[popover]:popover-open { opacity: 1; }
@starting-style { [popover]:popover-open { opacity: 0; } }

@media (prefers-reduced-motion: reduce) {
  .toast, .spinner { animation: none; }
}

.card { transition: scale 200ms ease, rotate 200ms ease; }
.card:hover { scale: 1.03; }

.icon-chevron { rotate: 0deg; transition: rotate 150ms; }
details[open] .icon-chevron { rotate: 90deg; }

.menu {
  transform-origin: top right;     /* grow from the corner */
  scale: 0.95;
  opacity: 0;
}
.menu.open { scale: 1; opacity: 1; }

/* order matters in the transform function list */
.a { transform: rotate(45deg) translateX(100px); }  /* moves diagonally */
.b { transform: translateX(100px) rotate(45deg); }  /* moves right, then spins */

/* group without repetition */
:is(article, aside) :is(h2, h3) { margin-block-start: 1.5em; }

/* zero-specificity default, easily overridden by any class */
:where(button) { font: inherit; cursor: pointer; }

/* card layout changes when it contains an image */
.card:has(> img) { display: grid; grid-template-columns: 120px 1fr; }

/* style a label whose checkbox is checked */
label:has(input:checked) { font-weight: 600; }

/* highlight the whole form row with an invalid field */
.field:has(input:user-invalid) { border-left: 3px solid crimson; }

/* no page scroll while a modal is open */
body:has(dialog[open]) { overflow: hidden; }

.card {
  padding: 1rem;
  border-radius: 12px;

  & h2 { margin-block: 0 0.5rem; }        /* .card h2 */
  & > img { width: 100%; }                 /* .card > img */
  &:hover { box-shadow: 0 4px 16px rgb(0 0 0 / 10%); }
  &.featured { border: 2px solid gold; }   /* .card.featured */
  [data-theme="dark"] & { background: #1f2937; }  /* ancestor context */

  @media (width >= 48rem) {
    padding: 2rem;                         /* .card at wide widths */
  }
}

/* <div class="slot"><article class="card"><img><div>...</div></article></div> */
.slot { container-type: inline-size; }

.card { display: grid; gap: 0.75rem; }        /* narrow: stacked */
.card h2 { font-size: clamp(1rem, 5cqi, 1.75rem); }  /* scales with the slot */

@container (width >= 30rem) {                  /* wide slot: side by side */
  .card { grid-template-columns: 160px 1fr; }
}

/* named container */
.sidebar { container: sidebar / inline-size; }
@container sidebar (width < 15rem) {
  .card img { display: none; }
}

@layer reset, vendor, base, components, utilities;

@import url("datepicker.css") layer(vendor);   /* can't beat our layers */

@layer reset {
  *, *::before, *::after { box-sizing: border-box; margin: 0; }
}
@layer base {
  a { color: var(--link, royalblue); }
}
@layer components {
  #sidebar .card h2 { margin-block-end: 1rem; }  /* high specificity... */
}
@layer utilities {
  .mb-0 { margin-block-end: 0; }               /* ...still loses to this */
}

/* unlayered: beats every layer above */
.legacy-banner h2 { margin: 2rem; }

/* <header class="a"><div class="menu">Menu</div></header> <main class="b">...</main> */
.a { position: relative; z-index: 1; }   /* stacking context */
.menu { position: absolute; z-index: 9999; }  /* only 9999 INSIDE .a */
.b { position: relative; z-index: 2; }   /* paints above all of .a, menu included */

/* fix: raise the context, not the child */
.a { z-index: 3; }

/* contain a component's internal layering */
.card { isolation: isolate; }
.card .badge { position: absolute; z-index: 2; }  /* can't leak above other cards' overlays */

:root { --z-dropdown: 10; --z-sticky: 20; --z-modal: 30; }

@layer reset, base, components, utilities;

@layer components {
  /* BEM: one class per selector, flat specificity */
  .card { padding: var(--space-4); border-radius: var(--radius-md); }
  .card__title { font-size: var(--text-lg); }
  .card--featured { border: 2px solid var(--color-accent); }
}

/* @scope: styles apply inside .card but stop at .card__content */
@scope (.card) to (.card__content) {
  img { border-radius: var(--radius-md); }
}

/* layout belongs to the parent, not to the children's margins */
.card-list { display: grid; gap: var(--space-4); }

/* <section class="box"><h2>Title</h2></section> */
.box { background: #eef; }
.box h2 { margin-top: 2rem; }   /* margin escapes: gap appears ABOVE .box */

.box { display: flow-root; }    /* new BFC: margin stays inside the box */

/* parent of floats collapsing to zero height */
.media { display: flow-root; }  /* contains the float */
.media img { float: left; margin-right: 1rem; }

/* gap below inline images (baseline alignment) */
.thumb img { display: block; }

/* margins collapse: 24px apart, not 40px */
p.a { margin-bottom: 16px; }
p.b { margin-top: 24px; }

/* cheap: composite-only animation */
.drawer { translate: -100% 0; transition: translate 250ms ease; will-change: translate; }
.drawer.open { translate: 0 0; }

/* expensive: animates layout every frame */
.drawer-bad { left: -300px; transition: left 250ms; }

/* long page: skip rendering sections until they near the viewport */
.article-section {
  content-visibility: auto;
  contain-intrinsic-size: auto 800px;   /* placeholder height for scrollbars */
}

/* widget whose internals never affect outside layout */
.chat-widget { contain: content; }

:root {
  color-scheme: light dark;
  --brand: oklch(55% 0.2 265);                       /* indigo */
  --brand-hover: oklch(from var(--brand) calc(l - 0.08) c h);
  --brand-soft: color-mix(in oklch, var(--brand), white 85%);
  --brand-50a: oklch(from var(--brand) l c h / 50%);
  --bg: light-dark(#ffffff, #0b1020);
  --fg: light-dark(#111827, #e5e7eb);
}
body { background: var(--bg); color: var(--fg); }
.button { background: var(--brand); }
.button:hover { background: var(--brand-hover); }
.tag { background: var(--brand-soft); }

.hero { background: linear-gradient(in oklch, oklch(70% 0.2 30), oklch(70% 0.2 250)); }

@media (color-gamut: p3) {
  .badge { background: color(display-p3 1 0.2 0.4); }
}

/* <div class="row"><aside>Nav</aside><main><pre>very long code line...</pre></main></div> */
.row { display: flex; }
.row aside { flex: 0 0 200px; }
.row main {
  flex: 1;
  min-width: 0;            /* without this, the long <pre> forces overflow */
}
.row pre { overflow-x: auto; }

/* grid: same trap with 1fr = minmax(auto, 1fr) */
.layout { display: grid; grid-template-columns: 240px minmax(0, 1fr); }

/* intrinsic keywords */
.tag { width: fit-content; }                          /* shrink-wrap a block */
.form { display: grid; grid-template-columns: max-content 1fr; gap: 0.5rem 1rem; }
